/* SsoPollCursorMapper.findByFeedType */
SELECT feed_type, last_since, last_polled_at, last_item_count, updated_at
FROM sso_poll_cursor
WHERE feed_type = #{feedType}

mapper.update:
/* SsoPollCursorMapper.updateCursor */
UPDATE sso_poll_cursor
SET last_since      = #{lastSince},
    last_polled_at  = #{lastPolledAt},
    last_item_count = #{lastItemCount}
WHERE feed_type = #{feedType}
